static _CLG_NF5_VAR0_SPLINE: OnceLock<RectBivariateSpline> = OnceLock::new();

/// Returns the degree-(3,3) interpolating spline over `CLg_nf5_var0`.
///
/// The spline is constructed on the **first call only**; every subsequent
